import{_ as i,o as t,c as a,a2 as r}from"./chunks/framework.CpZKh-tG.js";const m=JSON.parse('{"title":"PRD-026 — Historical content completeness pass (v0.7)","description":"","frontmatter":{},"headers":[],"relativePath":"prd/PRD-026.md","filePath":"prd/PRD-026.md"}'),s={name:"prd/PRD-026.md"};function o(l,e,n,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="prd-026-—-historical-content-completeness-pass-v0-7" tabindex="-1">PRD-026 — Historical content completeness pass (v0.7) <a class="header-anchor" href="#prd-026-—-historical-content-completeness-pass-v0-7" aria-label="Permalink to &quot;PRD-026 — Historical content completeness pass (v0.7)&quot;">​</a></h1><blockquote><p>Status · Shipped Date · 2026-06-09 Tracked by · GH issue #314 Builds on · PRD-004 (Mission Library) · PRD-012 (Spaceflight Fleet) · GH issue #311 (tier-by-tier brief)</p></blockquote><blockquote><p><strong>Why this is a PRD.</strong> Pre-v0.7 the historical record in /missions and /fleet was demonstrably NASA-skewed and Apollo-incomplete: only 3 of 11 crewed Apollo missions were in /missions, the surface-page hotspots on /moon + /mars referenced sites with no fleet entry behind them, and the global pre-2010 record had visible blind spots (no Luna 10, no SMART-1, no Chang&#39;e 6, no Mars Odyssey, no Lunar Orbiter 1–5, no pre-ISS Salyut 2/3/4/5). This PRD captures the work that closed those gaps so future audits have one place to point to instead of seven distinct tier commits.</p></blockquote><p><strong>Gating sentence</strong>: Captures the v0.7 retrospective on the historical-coverage backfill — the set of tiers (Phase 3c through Tier G) that filled missing missions, fleet entries, surface-page links, agency representation, and i18n coverage so the orrery honestly represents global space exploration history rather than a NASA-only slice.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Document the cumulative work that brought /missions, /fleet, /moon, /mars (and connected pages) to a state where:</p><ol><li>Every historically significant crewed lunar mission (Apollo 7–17) is in /missions</li><li>Every body that ships a surface-page hotspot has a fleet entry behind it</li><li>The fleet honestly surfaces non-NASA agencies (Roscosmos, CNSA, ISRO, ESA, UKSA, JAXA, USSF) at parity with NASA</li><li>Every fleet entry has en-US + 13 translated overlays (14 locales total)</li><li>Every fleet entry has a 5-image Wikimedia gallery with provenance</li><li>Every fleet ↔ mission ↔ surface-site cross-link is wired bidirectionally</li></ol><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Memory <code>feedback_global_space_program_representation</code>: &quot;Orrery celebrates global space programs, not just NASA&quot;. The pre-v0.7 state had /fleet skewed heavily toward NASA hardware with sparse coverage of the Soviet / Chinese / Indian / European programs. /missions had only 3 of the 11 crewed Apollo flights and missed every Apollo-era robotic mission. /moon and /mars hotspots showed surface sites with no fleet entry behind them.</p><p>This PRD groups the corrective work as one shipped slice (rather than re-narrating each tier individually).</p><h2 id="what-shipped-in-narrative-order" tabindex="-1">What shipped (in narrative order) <a class="header-anchor" href="#what-shipped-in-narrative-order" aria-label="Permalink to &quot;What shipped (in narrative order)&quot;">​</a></h2><h3 id="phase-3c-—-shuttle-fleet-commits-f6079424a-79c3c1914" tabindex="-1">Phase 3c — Shuttle fleet (commits f6079424a + 79c3c1914) <a class="header-anchor" href="#phase-3c-—-shuttle-fleet-commits-f6079424a-79c3c1914" aria-label="Permalink to &quot;Phase 3c — Shuttle fleet (commits f6079424a + 79c3c1914)&quot;">​</a></h3><ul><li>Columbia, Challenger, Discovery, Atlantis, Endeavour, Enterprise (the 6 NASA Space Shuttle orbiters by call sign)</li><li>X-37B (USSF reusable robotic spaceplane)</li><li>Buran OK-GLI (Roscosmos atmospheric analog, BTS-002)</li><li>Each: detail JSON + 14-locale i18n + 5 Wikimedia images + linked_iss_modules (Endeavour / Atlantis / Discovery wired to the 11 ISS modules they delivered)</li><li>ISS module schema bump: <code>launch_orbiter_fleet_id</code></li><li>Fleet entry schema bump: <code>linked_iss_modules</code></li></ul><h3 id="tier-a-—-apollo-missions-backfill-earth-dest-commit-590afb4f4" tabindex="-1">Tier A — Apollo missions backfill + EARTH dest (commit 590afb4f4) <a class="header-anchor" href="#tier-a-—-apollo-missions-backfill-earth-dest-commit-590afb4f4" aria-label="Permalink to &quot;Tier A — Apollo missions backfill + EARTH dest (commit 590afb4f4)&quot;">​</a></h3><ul><li>8 missing Apollo missions: Apollo 7 (EARTH), 8, 9 (EARTH), 10, 12, 14, 15, 16 — Apollo 11/13/17 were already present</li><li>New <code>EARTH</code> value added to the <code>dest</code> enum (schemas, TS type, <code>mission-dest.ts</code>, fly-mission-apply.ts cislunar branch, /missions filter pill, 14 locales)</li><li>Reciprocal <code>linked_missions</code> updated on saturn-v, saturn-ib, apollo-csm-block-ii, apollo-lm, lrv-apollo, lc-39a, lc-39b</li><li>Per-mission: base JSON + 14-locale i18n overlays</li><li>See <a href="https://github.com/chipi/orrery/issues/311" target="_blank" rel="noreferrer">GH #311 Tier A</a> for the original brief</li></ul><h3 id="tier-b-—-moon-surface-fleet-gaps-commit-79ab6b55b" tabindex="-1">Tier B — Moon-surface fleet gaps (commit 79ab6b55b) <a class="header-anchor" href="#tier-b-—-moon-surface-fleet-gaps-commit-79ab6b55b" aria-label="Permalink to &quot;Tier B — Moon-surface fleet gaps (commit 79ab6b55b)&quot;">​</a></h3><ul><li>8 new fleet entries (5 orbiters + 3 landers/sample-return) representing the global lunar exploration record: <ul><li>luna10 (Roscosmos, 1966) — first lunar orbiter</li><li>luna24 (Roscosmos, 1976) — last successful Soviet sample-return</li><li>lunar-prospector (NASA, 1998) — Discovery polar orbiter</li><li>smart-1 (ESA, 2003) — first European Moon mission</li><li>chandrayaan1 (ISRO, 2008) — discovered widespread surface water</li><li>lro (NASA, 2009-active) — LROC&#39;s 0.5 m/pixel imagery sources every Apollo/Luna/Chang&#39;e hotspot here</li><li>change1 (CNSA, 2007) — China&#39;s first lunar mission</li><li>change6 (CNSA, 2024) — first-ever lunar far-side sample return</li></ul></li><li>moon-sites.json now carries fleet_refs on all 8 site rows so the hotspot panel resolves to the fleet entry</li></ul><h3 id="tier-c-—-mars-surface-fleet-gaps-commit-8ace454e8" tabindex="-1">Tier C — Mars-surface fleet gaps (commit 8ace454e8) <a class="header-anchor" href="#tier-c-—-mars-surface-fleet-gaps-commit-8ace454e8" aria-label="Permalink to &quot;Tier C — Mars-surface fleet gaps (commit 8ace454e8)&quot;">​</a></h3><ul><li>7 new fleet entries (4 orbiters + 2 landers + 1 rover): <ul><li>viking1-orbiter (NASA, 1975-80) — first US Mars orbiter; first global Mars map</li><li>viking2-lander (NASA, 1976-80) — second US Mars lander, Utopia Planitia</li><li>mars3-orbiter (Roscosmos, 1971-72) — first measurements of Mars upper atmosphere temperature</li><li>mars6 (Roscosmos, 1973) — 224s of first direct atmospheric telemetry</li><li>mars-odyssey (NASA, 2001-active) — longest-lived Mars asset ever</li><li>beagle2 (UKSA / ESA, 2003) — found by HiRISE 2015</li><li>exomars-rosalind-franklin (ESA, planned 2028)</li></ul></li><li>mars-sites.json now carries fleet_refs on all 7 site rows</li></ul><h3 id="tier-d-—-lunar-orbiter-1-5-commit-6080a1d9f" tabindex="-1">Tier D — Lunar Orbiter 1-5 (commit 6080a1d9f) <a class="header-anchor" href="#tier-d-—-lunar-orbiter-1-5-commit-6080a1d9f" aria-label="Permalink to &quot;Tier D — Lunar Orbiter 1-5 (commit 6080a1d9f)&quot;">​</a></h3><ul><li>5 NASA precursor orbiters (1966-67) that mapped Apollo landing sites at 60 m/pixel — the highest-resolution global lunar map until LRO began LROC NAC in 2009</li><li>Parallels how Mariner 4/9 are split out as separate entries</li></ul><h3 id="tier-f-—-mission-counterparts-for-tier-b-commit-d1a15b75b" tabindex="-1">Tier F — Mission counterparts for Tier B (commit d1a15b75b) <a class="header-anchor" href="#tier-f-—-mission-counterparts-for-tier-b-commit-d1a15b75b" aria-label="Permalink to &quot;Tier F — Mission counterparts for Tier B (commit d1a15b75b)&quot;">​</a></h3><ul><li>4 robotic Moon missions that had fleet entries (Tier B) but no /missions counterpart: luna10, lunar-prospector, smart-1, change1</li><li>Per-mission: base JSON + 14-locale i18n + reciprocal fleet linked_missions wiring</li></ul><h3 id="tier-g-—-pre-iss-soviet-stations" tabindex="-1">Tier G — pre-ISS Soviet stations <a class="header-anchor" href="#tier-g-—-pre-iss-soviet-stations" aria-label="Permalink to &quot;Tier G — pre-ISS Soviet stations&quot;">​</a></h3><ul><li>4 stations: salyut-2, salyut-3, salyut-4, salyut-5 (the two military Almaz + DOS-4 civilian + last Almaz)</li><li>Completes the global pre-ISS station record (Mir, Skylab, Salyut 1/6/7 were already present)</li></ul><h2 id="cumulative-numbers-v0-7-historical-coverage-pass" tabindex="-1">Cumulative numbers (v0.7 historical-coverage pass) <a class="header-anchor" href="#cumulative-numbers-v0-7-historical-coverage-pass" aria-label="Permalink to &quot;Cumulative numbers (v0.7 historical-coverage pass)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Asset</th><th>Added</th><th>Total post-pass</th></tr></thead><tbody><tr><td>Mission entries</td><td>12 (8 Apollo + 4 robotic)</td><td>68</td></tr><tr><td>Fleet entries</td><td>32 (8 shuttle + 8 Moon + 7 Mars + 5 Lunar Orbiter + 4 Salyut)</td><td>246+</td></tr><tr><td>i18n overlay files</td><td>~520</td><td>full 14-locale parity across new content</td></tr><tr><td>Wikimedia hero images</td><td>~190</td><td>with per-image provenance</td></tr><tr><td>Cross-link entries</td><td>~80</td><td>bidirectional fleet ↔ mission ↔ surface</td></tr></tbody></table><h2 id="acceptance" tabindex="-1">Acceptance <a class="header-anchor" href="#acceptance" aria-label="Permalink to &quot;Acceptance&quot;">​</a></h2><ul><li>[x] /missions advertises 68 missions (was 56 pre-Tier-A)</li><li>[x] /fleet has new agency representation at parity — Tier B/C/D/G entries span Roscosmos / CNSA / ESA / ISRO / UKSA / USSF / Boeing OK alongside NASA per <a href="https://github.com/chipi/orrery/issues/311" target="_blank" rel="noreferrer">feedback_global_space_program_representation</a></li><li>[x] /moon + /mars hotspot panels link to the corresponding fleet entry where one exists (8 + 7 sites)</li><li>[x] Every new entry has en-US + 13 translations; preflight validates 14-locale parity</li><li>[x] Every new entry has 5 Wikimedia images (4 for change1, 2 for salyut-2 — both due to genuine Commons-category sparsity)</li><li>[x] preflight green on every commit; docker-e2e green after the count-drift e2e fixes</li><li>[x] All 7 tier commits pushed to main (see commit history)</li></ul><h2 id="out-of-scope-deferred" tabindex="-1">Out of scope (deferred) <a class="header-anchor" href="#out-of-scope-deferred" aria-label="Permalink to &quot;Out of scope (deferred)&quot;">​</a></h2><ul><li><strong>Tier H</strong> — operating-site UI per category (orbital vs surface) — was queued during the session; see issue #311 for the open ask</li><li><strong>Apollo by-call-sign split</strong> — discussed early in the session and explicitly declined: every Apollo LM/CM was single-use throwaway hardware, the call sign is effectively just the mission&#39;s hardware alias; better captured via per-mission JSON than per-vehicle fleet entries</li><li><strong>/plan multi-destination porkchop</strong> — Mars-only in v0.7 per ADR-076; v0.8 lands the other 11 destinations per RFC-026 + issue #312</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>GH issue #311 — original tier-by-tier brief</li><li>GH issue #312 — /plan multi-destination porkchop (v0.8)</li><li>GH issue #314 — this PRD&#39;s tracking issue</li><li>ADR-076 — /plan v0.7 Mars-only decision</li><li>RFC-026 — /plan v0.8 multi-destination expansion plan</li><li>AGENTS.md <code>feedback_global_space_program_representation</code> rule</li></ul>',33)])])}const u=i(s,[["render",o]]);export{m as __pageData,u as default};
